insert into kafaa_courses (id, programme_id, code, title_en, title_ar, modality, initial, mandatory, audience, competency_ids, objectives, prerequisites, duration_hours, qualifying, evaluation_form_id, owner_role, public_summary, summary_en, summary_ar, sources, packaging, pass_mark, validity_months, nexus_course_id, concept_content) values
('c-et-ghg-mgr', 'cld', 'ET-GR-101', 'GHG and ESG basics for managers', 'أساسيات غازات الدفيئة والحوكمة البيئية والاجتماعية للمديرين', 'elearning', false, false, 'staff', '{}'::text[], '[{"en":"Explain emission scopes, an emissions inventory and the difference between reductions and avoided emissions","ar":"شرح نطاقات الانبعاثات وجرد الانبعاثات والفرق بين التخفيض والانبعاثات التي تم تجنبها"},{"en":"Read a sustainability disclosure and find its main metrics, scope and date","ar":"قراءة إفصاح عن الاستدامة وتحديد مقاييسه الرئيسية ونطاقه وتاريخه"},{"en":"Describe the human capital reporting areas and the baseline metrics of ISO 30414:2025","ar":"وصف مجالات تقارير رأس المال البشري والمقاييس الأساسية في المعيار ISO 30414:2025"}]'::jsonb, '{}'::text[], 3, false, null, 'Corporate Sustainability', false, 'Three short modules for line managers: greenhouse-gas accounting basics, reading a sustainability disclosure, and human capital reporting concepts. Concept content; no figures about ENEC.', 'ثلاث وحدات قصيرة للمديرين المباشرين: أساسيات محاسبة غازات الدفيئة، وقراءة إفصاح عن الاستدامة، ومفاهيم تقارير رأس المال البشري. محتوى مفاهيمي، ولا أرقام عن المؤسسة.', '[{"id":"fs43-iso30414","label":"ISO TC 260 · ISO 30414:2025, strengthening human capital reporting (24 Aug 2025)","url":"https://committee.iso.org/sites/tc260/home/news/content-left-area/news-and-updates/iso-30414-2025-strengthening-hum.html","as_of":"2026-10-10"},{"id":"fs41-greencomp","label":"European Commission JRC · GreenComp, the European sustainability competence framework (2022)","url":"https://joint-research-centre.ec.europa.eu/greencomp","as_of":"2026-10-10"},{"id":"fs41-wef-foj","label":"World Economic Forum · Future of Jobs Report 2025, skills outlook","url":"https://www.weforum.org/publications/the-future-of-jobs-report-2025/in-full/3-skills-outlook/","as_of":"2026-10-10"}]'::jsonb, 'xapi', null, null, null, true),
('c-et-esg-clinic', 'cld', 'ET-GR-102', 'ESG data clinic: your team''s numbers', 'عيادة بيانات الحوكمة البيئية والاجتماعية: أرقام فريقك', 'clinic', false, false, 'staff', '{}'::text[], '[{"en":"Trace one of your team''s resource or emissions figures back to its source and scope","ar":"تتبّع أحد أرقام الموارد أو الانبعاثات لفريقك إلى مصدره ونطاقه"},{"en":"Draft a short qualitative explanation for a change in a metric, as ISO 30414:2025 asks","ar":"صياغة شرح نوعي قصير لتغيّر في أحد المقاييس، كما يطلب المعيار ISO 30414:2025"}]'::jsonb, array['c-et-ghg-mgr']::text[], 2, false, null, 'Corporate Sustainability', false, 'A two-hour facilitated clinic: managers bring one team metric, check its source and scope, and write the narrative that should accompany it.', 'عيادة بإشراف ميسّر لمدة ساعتين: يحضر المديرون مقياساً واحداً لفريقهم، ويتحققون من مصدره ونطاقه، ويكتبون الشرح الذي ينبغي أن يرافقه.', '[{"id":"fs43-iso30414","label":"ISO TC 260 · ISO 30414:2025, strengthening human capital reporting (24 Aug 2025)","url":"https://committee.iso.org/sites/tc260/home/news/content-left-area/news-and-updates/iso-30414-2025-strengthening-hum.html","as_of":"2026-10-10"},{"id":"fs41-greencomp","label":"European Commission JRC · GreenComp, the European sustainability competence framework (2022)","url":"https://joint-research-centre.ec.europa.eu/greencomp","as_of":"2026-10-10"}]'::jsonb, 'xapi', null, null, null, true)
insert into kafaa_hu_tools (id, name_en, name_ar, description_en, description_ar, kind, topic, sort, ai_en, ai_ar, trap_en, trap_ar, practice, example_en, example_ar, cues, trait_ids, drill_ids, lesson_ids) values
('hu-ai-bias', 'Automation bias check', 'فحص انحياز الأتمتة', 'Notice when you trust an answer because a tool produced it, and look for the evidence that would prove it wrong.', 'انتبه حين تثق بإجابة لأن أداة أنتجتها، وابحث عن الدليل الذي قد يثبت خطأها.', 'conditional', 'ai_automation', 1, '', '', 'A fluent, confident output feels finished. You stop reading the source, look only for information that agrees, and miss the one indication that does not.', 'يبدو المخرَج السلس الواثق مكتملاً، فتتوقف عن قراءة المصدر وتبحث فقط عمّا يوافقه، فيفوتك المؤشر الوحيد الذي يخالفه.', '[{"en":"Before you read the output, say what you expect it to say.","ar":"قبل أن تقرأ المخرَج، قل ما تتوقع أن يقوله."},{"en":"Find one independent indication or document that could contradict it.","ar":"ابحث عن مؤشر أو وثيقة مستقلة قد تناقضه."},{"en":"If they disagree, treat the tool as wrong until the controlled source shows otherwise: stop and ask.","ar":"إذا اختلفا، فاعتبر الأداة مخطئة إلى أن يُظهر المصدر الخاضع للرقابة غير ذلك: توقف واسأل."}]'::jsonb, 'Synthetic example: a summary says a pump''s valve line-up is complete; the controlled procedure has one more step after the vent valve.', 'مثال اصطناعي: يقول ملخّص إن اصطفاف صمامات مضخة مكتمل، بينما يتضمن الإجراء الخاضع للرقابة خطوة إضافية بعد صمام التنفيس.', array['confident','disagree','recommendation','time_pressure']::text[], array['trait-2','trait-5']::text[], array['ad-valve-lineup','ad-shift-turnover']::text[], array['oe-ai-01','oe-ai-03']::text[]),
('hu-ai-mode', 'Mode awareness', 'الوعي بنمط التشغيل', 'Know which mode a tool or automated system is in, and which revision, data set and time window its answer is based on.', 'اعرف النمط الذي تعمل فيه الأداة أو المنظومة المؤتمتة، والمراجعة ومجموعة البيانات والفترة الزمنية التي بُنيت عليها إجابتها.', 'conditional', 'ai_automation', 2, '', '', 'Mode confusion: the system is in automatic when you think it is in manual, or the tool answered from a superseded revision or yesterday''s data. "Why is it doing that?" is the warning sign.', 'التباس النمط: المنظومة في الوضع التلقائي وأنت تظنها يدوية، أو أجابت الأداة من مراجعة ملغاة أو من بيانات الأمس. وسؤال «لماذا تفعل ذلك؟» هو علامة التحذير.', '[{"en":"State the mode aloud in the brief and confirm it with three-way communication.","ar":"اذكر النمط بصوت مسموع في الإحاطة وأكّده بالاتصال الثلاثي."},{"en":"Check the revision, data date and scope the tool used before you use its answer.","ar":"تحقق من المراجعة وتاريخ البيانات والنطاق الذي استخدمته الأداة قبل أن تعتمد إجابتها."},{"en":"When the system surprises you, stop, go back to the procedure and ask before acting.","ar":"عندما تفاجئك المنظومة، توقف وارجع إلى الإجراء واسأل قبل أن تتصرف."}]'::jsonb, 'Synthetic example: a sampling summary quotes a limit from a superseded revision of the chemistry procedure.', 'مثال اصطناعي: ملخّص لإجراء أخذ العينات يقتبس حداً من مراجعة ملغاة لإجراء الكيمياء.', array['mode','alarm','revision','disagree']::text[], array['trait-2']::text[], array['ad-feedwater-sample','ad-requisition-qa']::text[], array['oe-ai-07','oe-ai-02']::text[]),
('hu-ai-reliance', 'Over-reliance and skill fade', 'الإفراط في الاعتماد وتراجع المهارة', 'Keep your own skill and attention in the job when a tool does most of the work.', 'حافظ على مهارتك وانتباهك في العمل حين تؤدي الأداة معظمه.', 'conditional', 'ai_automation', 3, '', '', 'When a tool usually gets it right, checking feels like a waste of time. Attention drifts, pre-filled entries are accepted as read, and the skill to do the task by hand fades.', 'حين تصيب الأداة عادةً، يبدو التحقق مضيعة للوقت؛ فيتشتت الانتباه وتُقبل الإدخالات المعبأة مسبقاً كأنها قُرئت، وتتراجع مهارة أداء المهمة يدوياً.', '[{"en":"Keep place on the controlled procedure, not on the tool''s checklist.","ar":"تتبّع موضعك على الإجراء الخاضع للرقابة لا على قائمة الأداة."},{"en":"Read every pre-filled entry as if you had to sign it yourself, because you do.","ar":"اقرأ كل إدخال معبأ مسبقاً كأنك ستوقّعه بنفسك، لأنك ستفعل."},{"en":"Do the key steps yourself from time to time, and ask for a peer check when the tool did most of the work.","ar":"نفّذ الخطوات الأساسية بنفسك من حين لآخر، واطلب تحقق زميل حين تكون الأداة قد أدّت معظم العمل."}]'::jsonb, 'Synthetic example: a generated maintenance checklist drops the torque re-check; the technician who worked from the procedure caught it.', 'مثال اصطناعي: قائمة صيانة مولّدة تُسقط إعادة فحص عزم الربط، فاكتشف ذلك الفني الذي عمل من الإجراء.', array['autofill','routine','time_pressure','handover']::text[], array['trait-1','trait-5']::text[], array['ad-mov-pm','ad-rwp-briefing']::text[], array['oe-ai-05','oe-ai-06']::text[]),
('hu-ai-verify', 'Verify against the controlled source', 'التحقق مقابل المصدر الخاضع للرقابة', 'A summary, translation or answer from a tool is a pointer. The controlled document at its current revision is the authority.', 'الملخص أو الترجمة أو الإجابة من أداة مجرد مؤشر؛ أما الوثيقة الخاضعة للرقابة بمراجعتها الحالية فهي المرجع.', 'core', 'ai_automation', 4, '', '', 'Using a tool''s summary in place of the procedure: values, order and omitted steps go unchecked, and an unsupported conclusion slips in.', 'استخدام ملخص الأداة بدلاً من الإجراء، فلا تُفحص القيم والترتيب والخطوات المحذوفة، ويتسلل استنتاج غير مدعوم.', '[{"en":"Open the controlled document at its current revision.","ar":"افتح الوثيقة الخاضعة للرقابة بمراجعتها الحالية."},{"en":"Compare values, step order, missing steps and anything the tool added or concluded.","ar":"قارن القيم وترتيب الخطوات والخطوات الناقصة وأي شيء أضافته الأداة أو استنتجته."},{"en":"Work from the controlled document; record what you checked and report the tool''s error.","ar":"اعمل من الوثيقة الخاضعة للرقابة، وسجّل ما تحققت منه، وأبلغ عن خطأ الأداة."}]'::jsonb, 'Synthetic example: an Arabic translation of a step reverses two actions; the English controlled procedure shows the right order.', 'مثال اصطناعي: ترجمة عربية لخطوة تعكس إجراءين، بينما يُظهر الإجراء الإنجليزي الخاضع للرقابة الترتيب الصحيح.', array['summary','controlled_source','revision','translation']::text[], array['trait-2','trait-5']::text[], array['ad-valve-lineup','ad-feedwater-sample','ad-requisition-qa']::text[], array['oe-ai-01','oe-ai-04']::text[])
insert into kafaa_oe_lessons (id, title_en, title_ar, summary_en, summary_ar, lesson_en, lesson_ar, source_kind, trait_ids, reviewed_on, reviewing_body, deidentified, status, affected_standard_ids, sample, topic, sources, hu_ids, drill_ids) values
('oe-ai-01', 'Digital twins and predictive maintenance are models of the plant', 'التوائم الرقمية والصيانة التنبؤية نماذج للمحطة', 'The IAEA Bulletin describes digital twins as AI-enhanced tools that analyse plant data to improve operations, and predictive maintenance as relying on digital replicas of real facilities.', 'تصف نشرة الوكالة الدولية للطاقة الذرية التوائم الرقمية بأنها أدوات معززة بالذكاء الاصطناعي تحلل بيانات المحطة لتحسين التشغيل، وتصف الصيانة التنبؤية بأنها تعتمد على نسخ رقمية من المنشآت الفعلية.', 'A twin or advisor is a model of the plant, not the plant: confirm its recommendation against plant indications and the controlled documents before you act on it.', 'التوأم أو المستشار نموذج للمحطة وليس المحطة نفسها: تحقق من توصيته مقابل مؤشرات المحطة والوثائق الخاضعة للرقابة قبل أن تتصرف بناءً عليها.', 'IAEA', array['trait-2','trait-5']::text[], '2026-10-10', 'OE Screening Committee', true, 'published', '{}'::text[], false, 'ai_automation', '[{"label":"IAEA Bulletin · Enhancing nuclear power production with artificial intelligence","url":"https://iaea.org/bulletin/enhancing-nuclear-power-production-with-artificial-intelligence","year":2025,"as_of":"2026-10-10"}]'::jsonb, array['hu-ai-bias','hu-ai-verify','hu-1']::text[], array['ad-mov-pm','ad-valve-lineup']::text[]),
('oe-ai-02', 'AI is arriving across the nuclear industry', 'الذكاء الاصطناعي يدخل قطاع الطاقة النووية بأكمله', 'The IAEA held its first symposium on AI and nuclear energy at its Vienna headquarters, framed as "Atoms for Algorithms" (reported December 2025).', 'عقدت الوكالة الدولية للطاقة الذرية أول ندوة لها عن الذكاء الاصطناعي والطاقة النووية في مقرها بفيينا تحت شعار «الذرّات من أجل الخوارزميات» (بحسب تقرير ديسمبر 2025).', 'Treat a new AI tool as a change to how work is done: brief it, train people on it, and keep the duty to challenge its output with the person doing the work.', 'تعامل مع أداة الذكاء الاصطناعي الجديدة كتغيير في طريقة العمل: قدّم لها إحاطة، ودرّب الناس عليها، وأبقِ واجب الاعتراض على مخرجاتها لدى من يؤدي العمل.', 'IAEA', array['trait-4','trait-7']::text[], '2026-10-10', 'OE Screening Committee', true, 'published', '{}'::text[], false, 'ai_automation', '[{"label":"NEI Magazine · IAEA hosts first AI nuclear symposium","url":"https://www.neimagazine.com/news/iaea-hosts-first-ai-nuclear-symposium/","year":2025,"as_of":"2026-10-10"}]'::jsonb, array['hu-ai-mode','hu-4']::text[], '{}'::text[]),
('oe-ai-03', 'Questioning an output is a behaviour that can be observed', 'التساؤل عن المخرَج سلوك يمكن ملاحظته', 'IAEA-TECDOC-1917 (2020) gives nuclear organisations methods to assess behavioural competencies, including structured interviews, simulation observation, 360-degree feedback and situational judgement.', 'تقدّم الوثيقة التقنية IAEA-TECDOC-1917 (2020) للمنظمات النووية أساليب لتقييم الكفاءات السلوكية، منها المقابلات المنظمة وملاحظة المحاكاة والتغذية الراجعة الشاملة والحكم الظرفي.', 'Challenging an AI output is part of a questioning attitude: practise it in situational-judgement practice and AI drills, and expect it to be observed in simulator debriefs.', 'الاعتراض على مخرَج الذكاء الاصطناعي جزء من موقف التساؤل: تدرّب عليه في تمارين الحكم الظرفي وتمارين الذكاء الاصطناعي، وتوقّع أن يُلاحَظ في جلسات المراجعة بعد المحاكاة.', 'IAEA', array['trait-2','trait-5']::text[], '2026-10-10', 'OE Screening Committee', true, 'published', '{}'::text[], false, 'ai_automation', '[{"label":"IAEA-TECDOC-1917 · Assessing Behavioural Competencies of Employees in Nuclear Facilities","url":"https://www-pub.iaea.org/MTCD/Publications/PDF/TE-1917_web.pdf","year":2020,"as_of":"2026-10-10"}]'::jsonb, array['hu-5','hu-ai-bias']::text[], array['ad-shift-turnover']::text[]),
('oe-ai-04', 'AI literacy goes with every system people use', 'الإلمام بالذكاء الاصطناعي يرافق كل نظام يستخدمه الناس', 'Article 4 of the EU AI Act, in application since 2 February 2025, asks providers and deployers of AI systems to ensure a sufficient level of AI literacy among the staff who use them. It does not bind ENEC; Kafa''a uses it as a voluntary international reference.', 'تطلب المادة 4 من قانون الذكاء الاصطناعي الأوروبي، السارية منذ 2 فبراير 2025، من مزوّدي أنظمة الذكاء الاصطناعي ومستخدميها ضمان مستوى كافٍ من الإلمام بالذكاء الاصطناعي لدى الموظفين الذين يستخدمونها. وهي لا تُلزم ENEC، وتستخدمها كفاءة مرجعاً دولياً طوعياً.', 'Before you rely on a tool''s output, know what that tool is approved for and complete the literacy measure listed for it in the AI-literacy register.', 'قبل أن تعتمد على مخرَج أداة، اعرف ما اعتُمدت له تلك الأداة وأكمل إجراء الإلمام المدرج لها في سجل الإلمام بالذكاء الاصطناعي.', 'EU AI Office', array['trait-1']::text[], '2026-10-10', 'OE Screening Committee', true, 'published', '{}'::text[], false, 'ai_automation', '[{"label":"European Commission · Repository of AI literacy practices (AI Act Article 4)","url":"https://digital-strategy.ec.europa.eu/en/policies/repository-ai-literacy-practices","year":2025,"as_of":"2026-10-10"}]'::jsonb, array['hu-ai-verify','hu-3','hu-4']::text[], '{}'::text[]),
('oe-ai-05', 'Completing a course is not the same as safe use', 'إتمام دورة لا يعني الاستخدام الآمن', 'The European Commission states that replicating the practices in its living repository of AI literacy practices does not automatically grant presumption of compliance with Article 4.', 'تنص المفوضية الأوروبية على أن تكرار الممارسات الواردة في مستودعها الحي لممارسات الإلمام بالذكاء الاصطناعي لا يمنح تلقائياً افتراض الامتثال للمادة 4.', 'A completion record shows that training happened, not that a person uses a tool safely: show it in the work, in drills, peer checks and observed practice.', 'يُثبت سجل الإتمام أن التدريب حدث، لا أن الشخص يستخدم الأداة بأمان: أظهِر ذلك في العمل وفي التمارين وتحقق الزملاء والممارسة الملاحَظة.', 'EU AI Office', array['trait-1','trait-7']::text[], '2026-10-10', 'OE Screening Committee', true, 'published', '{}'::text[], false, 'ai_automation', '[{"label":"European Commission · Repository of AI literacy practices (page updated July 2026)","url":"https://digital-strategy.ec.europa.eu/en/policies/repository-ai-literacy-practices","year":2026,"as_of":"2026-10-10"}]'::jsonb, array['hu-ai-reliance','hu-7']::text[], array['ad-rwp-briefing']::text[]),
('oe-ai-06', 'Keep a human-centred mindset', 'حافظ على عقلية تتمحور حول الإنسان', 'UNESCO''s AI competency frameworks (2024) place a human-centred mindset and the ethics of AI alongside AI techniques and system design, with progression from understanding to applying and creating.', 'تضع أطر كفاءات الذكاء الاصطناعي لدى اليونسكو (2024) العقلية المتمحورة حول الإنسان وأخلاقيات الذكاء الاصطناعي إلى جانب تقنيات الذكاء الاصطناعي وتصميم أنظمته، مع تدرّج من الفهم إلى التطبيق والإبداع.', 'The person stays accountable for a decision a tool informed: keep human judgement and the ethics of use ahead of convenience.', 'يبقى الشخص مسؤولاً عن القرار الذي دعمته أداة: قدّم الحكم البشري وأخلاقيات الاستخدام على السهولة.', 'UNESCO', array['trait-1','trait-5']::text[], '2026-10-10', 'OE Screening Committee', true, 'published', '{}'::text[], false, 'ai_automation', '[{"label":"UNESCO AI competency frameworks (GCED Clearinghouse record)","url":"https://gcedclearinghouse.org/en/node/146447","year":2024,"as_of":"2026-10-10"}]'::jsonb, array['hu-ai-reliance']::text[], '{}'::text[]),
('oe-ai-07', 'Know where a tool''s capability ends', 'اعرف أين تنتهي قدرة الأداة', 'The OECD AI Capability Indicators (2025) rate what AI systems can do across capability dimensions such as language, problem solving and metacognition, on a five-level scale, so it can be compared with what a task requires of people.', 'تقيّم مؤشرات قدرات الذكاء الاصطناعي لدى منظمة التعاون الاقتصادي والتنمية (2025) ما تستطيع أنظمة الذكاء الاصطناعي فعله عبر أبعاد قدرات مثل اللغة وحل المشكلات وما وراء المعرفة، على مقياس من خمسة مستويات، لمقارنته بما تتطلبه المهمة من الإنسان.', 'A tool that is strong with language can still be weak at judgement: match how hard you check to the gap between what the task needs and what the tool can do.', 'قد تكون الأداة قوية في اللغة وضعيفة في الحكم: اجعل مقدار تحققك على قدر الفجوة بين ما تتطلبه المهمة وما تستطيعه الأداة.', 'OECD', array['trait-2']::text[], '2026-10-10', 'OE Screening Committee', true, 'published', '{}'::text[], false, 'ai_automation', '[{"label":"OECD AI Capability Indicators · technical report","url":"https://digital-skills-jobs.europa.eu/en/latest/research/oecd-ai-capability-indicators-technical-report","year":2025,"as_of":"2026-10-10"}]'::jsonb, array['hu-ai-mode']::text[], array['ad-requisition-qa']::text[])
insert into kafaa_skill_evidence (id, person_id, skill_id, kind, ref_table, ref_id, level, basis, status, observed_on, note, recorded_by, active, created_at, org_id, contractor) values
